<?php
try{[$from,$to]=chr_report_range('monthly',$_GET);}catch(InvalidArgumentException $e){echo '<p>'.h($e->getMessage()).'</p>';return;}$events=chr_rows($pdo,'company_events');$edit=isset($_GET['edit'])?chr_record($pdo,'company_events',(int)$_GET['edit']):null;$v=$edit?array_merge($edit,$edit['values']):['start'=>date('Y-m-d'),'end'=>date('Y-m-d'),'all_day'=>true,'active'=>true,'audience'=>'Everyone'];
?><form class="card" method="get"><?php chr_hidden('page',$page);field('month','Month',$_GET+['month'=>date('Y-m')],'month',true);?><button class="button">Show month</button></form>
<?php if(can($pdo,$user,'calendar.manage')):?><details class="card" <?=$edit?'open':''?>><summary><?=$edit?'Edit event':'Add event'?></summary><form method="post" class="form-grid"><?php ftoken();chr_hidden('action','att_event');chr_hidden('id',$edit['id']??0);chr_hidden('version',$edit['version']??0);field('title','Event title',$v,'text',true,190);choose('type','Event type',$v,['Meeting','Training','Celebration','Company Event']);field('start','Start date',$v,'date',true);field('end','End date',$v,'date',true);chr_checkbox('all_day','All day',!empty($v['all_day']));field('start_time','Start time',$v,'time');field('end_time','End time',$v,'time');field('description','Description',$v,'text',false,5000);field('location','Location',$v,'text',false,250);choose('audience','Audience',$v,['Everyone','Department','Selected Employees']);chr_select('department_id','Department',$v['department_id']??'', [''=>'Select department']+$departmentOptions);?><label>Selected employees<select name="employee_ids[]" multiple><?php foreach($employeeOptions as $id=>$label):?><option value="<?=$id?>" <?=in_array($id,$v['employee_ids']??[])?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></label><?php chr_checkbox('active','Active event',!$edit||$edit['status']==='Active');?><div><button class="button primary">Save event</button></div></form></details><?php endif;?>
<?php $byDay=[];foreach($events as $event){$d=$event['values'];if($event['status']!=='Active'||$d['start']>$to||$d['end']<$from)continue;foreach(chr_dates(max($from,$d['start']),min($to,$d['end'])) as $date)$byDay[$date][]=['title'=>$event['title'],'type'=>$d['type'],'id'=>$event['id'],'audience'=>$d['audience']];}foreach(chr_rows($pdo,'holidays') as $holiday){$date=$holiday['values']['date']??'';if($holiday['status']==='Published'&&$date>=$from&&$date<=$to)$byDay[$date][]=['title'=>$holiday['title'],'type'=>'Holiday','id'=>0,'audience'=>'Everyone'];}
?><section class="card"><h2><?=h(date('F Y',strtotime($from)))?></h2><div class="company-calendar"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $label):?><strong><?=h($label)?></strong><?php endforeach;for($i=1;$i<(int)date('N',strtotime($from));$i++):?><div class="calendar-empty"></div><?php endfor;foreach(chr_dates($from,$to) as $date):?><div class="calendar-day <?=$date===date('Y-m-d')?'today':''?>"><strong><?=substr($date,8)?></strong><?php foreach($byDay[$date]??[] as $event):?><p><?php if($event['id']&&can($pdo,$user,'calendar.manage')):?><a href="?page=company_calendar&month=<?=substr($from,0,7)?>&edit=<?=$event['id']?>"><?=h($event['title'])?></a><?php else:echo h($event['title']);endif;?><small><?=h($event['type'].' · '.$event['audience'])?></small></p><?php endforeach;?></div><?php endforeach;?></div><p>Holidays are shown directly from the holiday configuration.</p></section>
